प्रत्येक फ़ोटॉन की ऊर्जा होगी

$$
\begin{aligned}
E & =h v=\left(6.63 \times 10^{-34} \mathrm{~J} \mathrm{~s}\right)\left(6.0 \times 10^{14} \mathrm{~Hz}\right) \\
& =3.98 \times 10^{-19} \mathrm{~J}
\end{aligned}
$$

$$
\begin{aligned}
N & =\frac{P}{E}=\frac{2.0 \times 10^{-3} \mathrm{~W}}{3.98 \times 10^{-19} \mathrm{~J}} \\
& =5.0 \times 10^{15} \text { फ़ोटॉन प्रति सेकंड }
\end{aligned}
$$

$$
\begin{aligned}
v_{0} & =\frac{\phi_{0}}{h}=\frac{2.14 \mathrm{eV}}{6.63 \times 10^{-34} \mathrm{Js}} \\
& =\frac{2.14 \times 1.6 \times 10^{-19} \mathrm{~J}}{6.63 \times 10^{-34} \mathrm{~J} \mathrm{~s}}=5.16 \times 10^{14} \mathrm{~Hz}
\end{aligned}
$$

$$
\begin{aligned}
& =\frac{\left(6.63 \times 10^{-34} \mathrm{Js}\right) \times\left(3 \times 10^{8} \mathrm{~m} / \mathrm{s}\right)}{(0.60 \mathrm{eV}+2.14 \mathrm{eV})} \\
& =\frac{19.89 \times 10^{-26} \mathrm{Jm}}{(2.74 \mathrm{eV})} \\
\lambda & =\frac{19.89 \times 10^{-26} \mathrm{~J} \mathrm{~m}}{2.74 \times 1.6 \times 10^{-19} \mathrm{~J}}=454 \mathrm{~nm}
\end{aligned}
$$

$$
\begin{aligned}
& =\frac{6.63 \times 10^{-34} \mathrm{~J} \mathrm{~s}}{4.92 \times 10^{-24} \mathrm{~kg} \mathrm{~m} / \mathrm{s}} \\
\lambda & =0.135 \mathrm{~nm}
\end{aligned}
$$

तब संवेग

$$
\begin{aligned}
& p^{\prime}=m^{\prime} v^{\prime}=0.150(\mathrm{~kg}) \times 30.0(\mathrm{~m} / \mathrm{s}) \\
& p^{\prime}=4.50 \mathrm{~kg} \mathrm{~m} / \mathrm{s}
\end{aligned}
$$

$$
\begin{aligned}
& =\frac{6.63 \times 10^{-34} \mathrm{~J} \mathrm{~s}}{4.50 \times \mathrm{kg} \mathrm{~m} / \mathrm{s}} \\
\lambda^{\prime} & =1.47 \times 10^{-34} \mathrm{~m}
\end{aligned}
$$

ऊर्जा का सूत्र प्रयोग करने पर

$$
\begin{aligned}
& E=e V=h v \\
& n=\frac{e V}{h}=\frac{1.6 \times 10^{-19} \times 30 \times 10^{3}}{6.63 \times 10^{-34}}=7.24 \times 10^{18} \mathrm{~Hz}
\end{aligned}
$$

$\therefore$ जहाँ,

$$
\begin{aligned}
c & =3 \times 10^{8} \mathrm{~m} / \mathrm{s} \text { (प्रकाश की चाल) } \\
\lambda & =0.414 \times 10^{-10} \\
& =0.0414 \times 10^{-9} \mathrm{~m} \\
& =0.0414 \mathrm{~nm}
\end{aligned}
$$

उत्सर्जित इलेक्ट्रॉन की अधिकतम ऊर्जा (आइन्सटीन फोटो इलेक्ट्रिक समीकरण)

$$
\begin{aligned}
K E_{\max } & =h v-\phi_{0} \\
& =\frac{6.63 \times 10^{-34} \times 6 \times 10^{14}}{1.6 \times 10^{-19}}-2.14 \\
& =0.35 \mathrm{eV}
\end{aligned}
$$

हम जानते हैं कि

$$
\begin{aligned}
K E_{\max } & =e V_{0} \\
0.35 \mathrm{eV} & =e V_{0} \\
V_{0} & =0.35 \mathrm{~V}
\end{aligned}
$$

अथवा

$$
\begin{aligned}
& v_{\max }=350713.55 \mathrm{~m} / \mathrm{s} \\
& v_{\max }=350.7 \mathrm{~km} / \mathrm{s}
\end{aligned}
$$

अधिकतम गतिज ऊर्जा का सूत्र

$$
\begin{aligned}
K E_{\max } & =e V_{0}=1.5 \mathrm{eV} \\
& =1.5 \times 1.6 \times 10^{-19}=2.4 \times 10^{-19} \mathrm{~J}
\end{aligned}
$$

माना प्रति सेकण्ड फोटॉनों की संख्या $n$ है, तब

$$
\begin{aligned}
n & =\frac{\text { शक्ति }}{\text { प्रति सेकण्ड फोटॉनों की संख्या }}=\frac{9.42 \times 10^{-3}}{3.14 \times 10^{-19}} \\
& =3 \times 10^{16} \text { photon } / \mathrm{s}
\end{aligned}
$$

दिया है, एकवर्णी प्रकाश का तरंगदेर्घ्य, $\lambda=632.8 \mathrm{~nm}$

$$
\begin{aligned}
&=632.8 \times 10^{-9} \mathrm{~m} \\
& \text { शक्ति }=9.42 \mathrm{~mW}=9.42 \times 10^{-3} \mathrm{~W}
\end{aligned}
$$

हम जानते हैं कि

$$
\begin{aligned}
h v & =e V \\
\frac{v}{v} & =\frac{h}{e} \\
\frac{h}{e} & =4.12 \times 10^{-15} \\
h & =1.6 \times 10^{-19} \times 4.12 \times 10^{-15} \\
& =6.592 \times 10^{-34} \mathrm{~J}-\mathrm{s}
\end{aligned}
$$

गतिज ऊर्जा का सूत्र प्रयोग करने पर

$$
\begin{aligned}
K E & =e V_{0}=h v-h v_{0} \\
V_{0} & =\frac{h\left(v-v_{0}\right)}{e}=\frac{6.63 \times 10^{-34}\left(8.2 \times 10^{14}-3.3 \times 10^{14}\right)}{1.6 \times 10^{-19}} \\
& =\frac{6.63 \times 10^{-34} \times 10^{14} \times 4.9}{1.6 \times 10^{-19}} \\
& =2.03 \mathrm{~V}
\end{aligned}
$$

प्रकाश-विद्युत उत्सर्जन केवल तभी संभव है जब प्रत्येक फोटॉन की ऊर्जा कार्य-फलन से अधिक हो

$$
\begin{aligned}
E & =\frac{h c}{\lambda}=\frac{6.63 \times 10^{-34} \times 3 \times 10^{8}}{330 \times 10^{-9}} \\
& =6.027 \times 10^{-19} \mathrm{~J}
\end{aligned}
$$

अथवा

$$
\begin{aligned}
v_{0} & =7.21 \times 10^{14}-2.47 \times 10^{14} \quad\left(\because v=7.21 \times 10^{14} \mathrm{~Hz}\right) \\
& =4.74 \times 10^{14} \mathrm{~Hz}
\end{aligned}
$$

गतिज ऊर्जा

$$
\begin{gathered}
K E=e V_{0}=\frac{h c}{\lambda}-\phi_{0} \\
1.6 \times 10^{-19} \times 0.38=\frac{6.63 \times 10^{-34} \times 3 \times 10^{8}}{488 \times 10^{-9}}-\phi_{0}
\end{gathered}
$$

$$
\begin{aligned}
& =\frac{34.67 \times 10^{-20}}{1.6 \times 10^{-19}} \mathrm{eV} \\
& =2.17 \mathrm{eV}
\end{aligned}
$$

$$
\begin{aligned}
\lambda & =\frac{h}{m v}=\frac{6.63 \times 10^{-34}}{0.040 \times 1 \times 10^{3}} \quad\left(\begin{array}{rl}
\because \quad m & =0.040 \mathrm{~kg} \\
v & =1 \mathrm{~km} / \mathrm{s} \\
& =1000 \mathrm{~m} / \mathrm{s}
\end{array}\right) \\
& =1.66 \times 10^{-35} \mathrm{~m}
\end{aligned}
$$

$$
\begin{aligned}
\lambda & =\frac{h}{m v}=\frac{6.63 \times 10^{-34}}{0.060 \times 1000} \\
& =1.1 \times 10^{-35} \mathrm{~m}
\end{aligned}
$$

$$
\begin{aligned}
\lambda & =\frac{h}{m v}=\frac{6.63 \times 10^{-34}}{1 \times 10^{-9} \times 2.2} \\
& =3.0 \times 10^{-25} \mathrm{~m}
\end{aligned}
$$
